g_j (v) = \begin{cases}  e^{ - {{op:bruch|1|( \delta_j^2- {{op:Betrag|v|}}^2 )^2}} }\,  {{textfür|}}  {{op:betrag|v|}} < \delta_j \, , \\   0 \text{ sonst} \, , \end{cases}
