{{
Mathematischer Text/Beweis{{{opt|}}}
|Text=
{{
Beweisstruktur
|Strategie=
|Notation=
|Beweis=
Da beide Seiten dieser Gleichung linear in {{math|term=\omega|SZ=}} sind, können wir annehmen, dass  {{math|term=\omega|SZ=}} die Form {{mathl|term=\omega=f dx_2  {{wedgedots|}} dx_n |SZ=}} besitzt. Wir schreiben den Quader als {{mathl|term=Q=[a,b] \times \tilde{Q}|SZ=.}} Aufgrund
{{
Faktlink
|Präwort=des|Satzes von Fubini|Faktseitenname=
Sigmaendliche Räume/Satz von Fubini/Fakt
|Refname={{{ref|}}}|refb={{{refb|}}}
|SZ=,
}}
{{
Faktlink
|Präwort=des|Hauptsatzes der Infinitesimalrechnung|Faktseitenname=
Stammfunktion/Riemann Integral/Hauptsatz/Fakt
|Refname={{{ref|}}}|refb={{{refb|}}}
|SZ=
}}
{{
Zusatz/Klammer
|text=angewendet auf jedes fixierte {{mathl|term=(x_2  {{kommadots|}} x_n)|SZ=}} |
|ISZ=|ESZ=
}}
und
{{
Faktlink
||Faktseitenname=
Differentialform/Lokal/Zurückziehen unter partiell konstanter Abbildung/Fakt
|Refname={{{ref|}}}|refb={{{refb|}}}
|SZ=
}}
{{
Zusatz/Klammer
|text=angewendet auf alle bis auf zwei Seiten|
|ISZ=|ESZ=
}}
gilt
{{
Ma:Vergleichskette/align
| {{op:integralform|d\omega|Q}} 
||{{op:integralform|df \wedge  dx_2  {{wedgedots|}} dx_n  |Q}} 
||{{op:integralform| ( \sum_{j {{=|}} 1}^n  {{op:partiell|f|x_j}} dx_j )  \wedge  dx_2  {{wedgedots|}} dx_n  |Q}} 
||{{op:integralform|   {{op:partiell|f|x_1}} dx_1 \wedge  dx_2  {{wedgedots|}} dx_n  |Q}} 
||{{op:integralform| ( {{op:integralform|  {{op:partiell|f|x_1}} dx_1|[a,b] }} )  dx_2  {{wedgedots|}} dx_n  |\tilde{Q} }} 
||{{op:integralform| ( f(b,x_2  {{kommadots|}} x_n ) - f(a,x_2  {{kommadots|}} x_n ))  dx_2  {{wedgedots|}} dx_n  |\tilde{Q} }} 
|| \sum_{S \text{ orientierte Seite von } Q}{{op:integralform|f dx_2  {{wedgedots|}} dx_n |S}}
|| {{op:integralform|f dx_2  {{wedgedots|}} dx_n |\partial Q}} 
|| {{op:integralform|\omega|\partial Q}} 
|SZ=.
}}
|Abschluss=
}}
|Textart=Beweis 
|Kategorie=Der Satz von Stokes
|Kategorie2=
|Kategorie3=
|Objektkategorie= 
|Stichwort=
|Autor=
|Bearbeitungsstand=
}}

{{
Mathematischer Text/Beweis{{{opt|}}}
|Text=
{{
Beweisstruktur
|Strategie=
|Notation=
|Beweis=
Da beide Seiten dieser Gleichung linear in {{math|term=\omega|SZ=}} sind, können wir annehmen, dass  {{math|term=\omega|SZ=}} die Gestalt {{mathl|term=\omega=f dx_2  {{wedgedots|}} dx_n |SZ=}} mit einer in einer offenen Umgebung von {{math|term=Q|SZ=}} definierten stetig differenzierbaren Funktion {{math|term=f|SZ=}} besitzt. Wir schreiben den Quader als {{mathl|term=Q=[a,b] \times \tilde{Q}|SZ=.}} Aufgrund
{{
Faktlink
|Präwort=des|Satzes von Fubini|Faktseitenname=
Sigmaendliche Räume/Satz von Fubini/Fakt
|Refname={{{ref|}}}|refb={{{refb|}}}
|SZ=,
}}
{{
Faktlink
|Präwort=des|Hauptsatzes der Infinitesimalrechnung|Faktseitenname=
Stammfunktion/Riemann Integral/Hauptsatz/Fakt
|Refname={{{ref|}}}|refb={{{refb|}}}
|SZ=
}}
{{
Zusatz/Klammer
|text=angewendet auf jedes fixierte {{mathl|term=(x_2  {{kommadots|}} x_n)|SZ=}} |
|ISZ=|ESZ=
}}
und
{{
Faktlink
||Faktseitenname=
Differentialform/Lokal/Zurückziehen unter partiell konstanter Abbildung/Fakt
|Refname={{{ref|}}}|refb={{{refb|}}}
|SZ=
}}
{{
Zusatz/Klammer
|text=angewendet auf alle Seiten bis auf 
{{
mathkor|term1=
a \times \tilde{Q}
|und|term2=
b \tilde{Q}
|SZ=
}}zwei Seiten|
|ISZ=|ESZ=
}}
gilt
{{
Ma:Vergleichskette/align
| {{op:integralform|d\omega|Q}} 
||{{op:integralform|df \wedge  dx_2  {{wedgedots|}} dx_n  |Q}} 
||{{op:integralform| ( \sum_{j {{=|}} 1}^n  {{op:partiell|f|x_j}} dx_j )  \wedge  dx_2  {{wedgedots|}} dx_n  |Q}} 
||{{op:integralform|   {{op:partiell|f|x_1}} dx_1 \wedge  dx_2  {{wedgedots|}} dx_n  |Q}} 
||{{op:integralform| ( {{op:integralform|  {{op:partiell|f|x_1}} dx_1|[a,b] }} )  dx_2  {{wedgedots|}} dx_n  |\tilde{Q} }} 
||{{op:integralform| ( f(b,x_2  {{kommadots|}} x_n ) - f(a,x_2  {{kommadots|}} x_n ))  dx_2  {{wedgedots|}} dx_n  |\tilde{Q} }} 
||{{op:integralform|f dx_2  {{wedgedots|}} dx_n |b \times \tilde{Q} }}  - {{op:integralform|f dx_2  {{wedgedots|}} dx_n |a \times \tilde{Q} }}  
|| \sum_{S \text{ orientierte Seite von } Q}{{op:integralform|f dx_2  {{wedgedots|}} dx_n |S}}
|| {{op:integralform|f dx_2  {{wedgedots|}} dx_n |\partial Q}} 
|| {{op:integralform|\omega|\partial Q}} 
|SZ=.
}}
|Abschluss=
}}
|Textart=Beweis 
|Kategorie=Der Satz von Stokes
|Kategorie2=
|Kategorie3=
|Objektkategorie= 
|Stichwort=
|Autor=
|Bearbeitungsstand=
}}

