{{
Mathematischer Text/Lösung{{{opt|}}}
|Text=
Die einzige Standardableitung auf {{math|term= \R |SZ=}}  ist {{math|term= \partial |SZ=,}} deshalb verzichten wir auf einen unteren Index für die Christoffelsymbole. Nach
{{
Faktlink
|Faktseitenname=
Linearer Zusammenhang/Vertikale Ableitung/Längs Abbildung/Eigenschaften/Fakt
|Nr=2
|SZ=
}}
ist für
{{
Vergleichskette
| \ell,k
|| 1,2
|| 
|| 
|| 
|SZ=
}}
{{
Vergleichskette/display
| \tilde{\Gamma}_\ell^k (t)
|| \psi_1'(t) \Gamma_{1 \ell}^k (\psi(t)) + \psi'_2(t) \Gamma_{2 \ell}^k (\psi(t))
|| \Gamma_{1 \ell}^k (t,e^t)   + e^t \Gamma_{2 \ell}^k (t,e^t)
|SZ=.
}}
Mit
{{
Beispiellink
|Beispielseitenname=
Halbebene/Poincaré/Riemannsche Geometrie/Christoffelsymbole/Beispiel
|Nr=
|SZ=
}}
ergibt sich
{{
Vergleichskette/display
| \tilde{\Gamma}_1^1 (t)
|| \Gamma_{1 1}^1 (t,e^t) + e^t \Gamma_{2 1}^1 (t,e^t)
||  -e^t e^{-t}
|| -1
|| 
|SZ=,
}}
{{
Vergleichskette/display
| \tilde{\Gamma}_1^2 (t)
|| \Gamma_{1 1}^2 (t,e^t) + e^t \Gamma_{2 1}^2 (t,e^t)
|| e^{-t}  
|| 
|| 
|SZ=,
}}
{{
Vergleichskette/display
| \tilde{\Gamma}_2^1 (t)
|| \Gamma_{1 2}^1 (t,e^t) + e^t \Gamma_{2 2}^1 (t,e^t)
||  -e^{-t}  
|| 
|| 
|SZ=
}}
und
{{
Vergleichskette/display
| \tilde{\Gamma}_2^2 (t)
|| \Gamma_{1 2}^2 (t,e^t) + e^t \Gamma_{2 2}^2 (t,e^t)
|| - e^t e^{-t}
|| -1
|| 
|SZ=.
}}
|Textart=Lösung 
|Kategorie=Siehe
|Kategorie2=
|Autor=
|Bearbeitungsstand=wd
}}

